"""Generate exact palette/title-stack fixtures from the retained XTerm capture."""
import argparse
import json
from pathlib import Path

root=Path(__file__).resolve().parents[1]
source=json.loads((root/'research/palette-stack-evidence/xterm.json').read_text(encoding='utf-8'))
cases=[(name,c['sequence'],c['reply']) for name,c in source['cases'].items()]

def literal(text):
    return '"'+''.join('\\%03o'%b if b<32 or b>=127 else
        '\\'+chr(b) if chr(b) in '\\"' else chr(b) for b in text.encode())+'"'

outputs={
    'palette_stack_oracle_cases.h':'/* Generated by tests/generate_palette_stack_oracle.py. */\n'+
        'static const struct { const char *name, *sequence, *reply; } palette_stack_oracle[] = {\n'+
        ''.join('    {'+', '.join(map(literal,c))+'},\n' for c in cases)+'};\n',
    'palette_stack_oracle_cases.py':'# Generated by tests/generate_palette_stack_oracle.py.\nCASES = [\n'+
        ''.join('    '+repr(c)+',\n' for c in cases)+']\n',
}
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check',action='store_true')
args=parser.parse_args()
for name,content in outputs.items():
    path=root/'tests'/name
    if args.check:assert path.read_text(encoding='utf-8')==content,'Regenerate '+name
    else:path.write_text(content,encoding='utf-8')
print(f'{len(cases)} exact XTerm palette/title-stack cases')
